import{_ as a,c as t,o as r,aj as s}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Primitive","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(o,e,l,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="primitive" tabindex="-1">Primitive <a class="header-anchor" href="#primitive" aria-label="Permalink to “Primitive”">​</a></h1><p>Primitive provides authentication, data sync, file storage, and server-side logic for web and iOS apps. Build your UI and business logic while Primitive manages the backend.</p><p>Start with a template that includes sign-in and synced data, or use the JavaScript and Swift client libraries in an existing app.</p><h2 id="from-idea-to-production" tabindex="-1">From Idea to Production <a class="header-anchor" href="#from-idea-to-production" aria-label="Permalink to “From Idea to Production”">​</a></h2><ol><li><strong>Create an app</strong> with the web or iOS starter template.</li><li><strong>Add data</strong> in databases that sync to every device, or stay on the server behind your functions.</li><li><strong>Add server-side logic</strong> to process data, run AI prompts, or call external services.</li><li><strong>Deploy</strong> your web app, or distribute your iOS app through TestFlight and the App Store.</li></ol><p>Follow the <a href="./getting-started/template-app.html">Quick Start</a>, or explore the <a href="./getting-started/example-apps.html">Example Apps</a>.</p><h2 id="why-primitive" tabindex="-1">Why Primitive? <a class="header-anchor" href="#why-primitive" aria-label="Permalink to “Why Primitive?”">​</a></h2><ul><li><strong>Built-in collaboration.</strong> Databases sync to every device that uses them, so the app reads instantly, works offline and shows every change live. Concurrent edits merge automatically.</li><li><strong>A shared backend for web and iOS.</strong> Use the same users, data, and access rules from both clients.</li><li><strong>Configuration in your repository.</strong> Manage backend services through the CLI, either directly or with a coding agent.</li></ul><h2 id="what-primitive-provides" tabindex="-1">What Primitive Provides <a class="header-anchor" href="#what-primitive-provides" aria-label="Permalink to “What Primitive Provides”">​</a></h2><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h3><p>Sign in with Google, passwordless email, or passkeys. Primitive manages sessions and token refresh.</p><h3 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to “Data Storage”">​</a></h3><ul><li><strong>Databases</strong> hold your app&#39;s records and answer queries across them. Share each one with the users or groups that need it.</li><li><strong>Synced</strong> databases live on every device that uses them, for instant, offline, live and collaborative data.</li><li><strong>Server-only</strong> databases stay behind your server functions, which decide what each caller may see.</li></ul><p><a href="./getting-started/databases.html">Databases</a> explains how to choose.</p><h3 id="users-and-groups" tabindex="-1">Users and Groups <a class="header-anchor" href="#users-and-groups" aria-label="Permalink to “Users and Groups”">​</a></h3><p>Each user has a profile. Organize users into teams or roles, then use those relationships in access rules.</p><h3 id="server-functions" tabindex="-1">Server Functions <a class="header-anchor" href="#server-functions" aria-label="Permalink to “Server Functions”">​</a></h3><p>Run TypeScript on the server to read and write data, call services, and enforce business rules. Call a function from your app, run it as a background task, or trigger it with a webhook or schedule.</p><h3 id="managed-prompts" tabindex="-1">Managed Prompts <a class="header-anchor" href="#managed-prompts" aria-label="Permalink to “Managed Prompts”">​</a></h3><p>Define and test reusable AI prompts, keep them in version control, and run them from server functions.</p><h3 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to “Integrations”">​</a></h3><p>Call external APIs from server functions. Primitive stores credentials on the server and adds them to requests.</p><h3 id="blob-storage" tabindex="-1">Blob Storage <a class="header-anchor" href="#blob-storage" aria-label="Permalink to “Blob Storage”">​</a></h3><p>Store images, PDFs, and other files. Attach files to a database to use its permissions, or use a bucket for files managed independently.</p><h3 id="sharing-and-access" tabindex="-1">Sharing and Access <a class="header-anchor" href="#sharing-and-access" aria-label="Permalink to “Sharing and Access”">​</a></h3><p>Share databases with users or groups. Invite teammates by email, or let users request access to a database.</p><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to “Analytics”">​</a></h3><p>Track user activity and platform events automatically. Add custom events and query results through the Admin Console, CLI, or server functions.</p><h2 id="how-it-fits-together" tabindex="-1">How It Fits Together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to “How It Fits Together”">​</a></h2><p>Your app uses a client library to authenticate users, access data, and call server functions. The web and iOS templates add sign-in screens, data-binding helpers, and development tools.</p><p>Manage the backend through the CLI or the <a href="https://admin.primitiveapi.com" target="_blank" rel="noreferrer">Admin Console</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./getting-started/template-app.html">Quick Start</a></strong> — Create and run an app</li><li><strong><a href="./getting-started/databases.html">Databases</a></strong> — Store, sync and share your app&#39;s data</li><li><strong><a href="./getting-started/database-patterns.html">Data Patterns and Partitioning</a></strong> — Worked designs for common apps</li></ul>',33)])])}const g=a(i,[["render",n]]);export{m as __pageData,g as default};
